    code: "import numpy as np\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.cluster import KMeans\n\nX = np.array([[1, 1], [1, 2], [8, 8], [9, 8]])\ny = np.array([0, 0, 1, 1])                     # labels\n\nsup = LogisticRegression().fit(X, y)           # supervised\nprint(\"Supervised predict [8, 9]:\", sup.predict([[8, 9]])[0])\n\nkm = KMeans(n_clusters=2, n_init=10, random_state=0).fit(X)  # no labels\nprint(\"Unsupervised clusters:\", km.labels_.tolist())\n\n# Reinforcement: pick the action with the best average reward\nrewards = {\"left\": [0, 1, 0], \"right\": [1, 1, 1]}\nbest = max(rewards, key=lambda k: np.mean(rewards[k]))\nprint(\"RL agent learns to go:\", best)",
