    code: "import numpy as np\nimport pandas as pd\nfrom sklearn.impute import SimpleImputer\n\ndf = pd.DataFrame({\"age\": [25, np.nan, 35, 40],\n                   \"city\": [\"Pune\", \"Delhi\", np.nan, \"Pune\"]})\nprint(\"Missing per column:\")\nprint(df.isna().sum())\n\ndf[\"age\"] = SimpleImputer(strategy=\"median\").fit_transform(df[[\"age\"]]).ravel()\ndf[\"city\"] = SimpleImputer(strategy=\"most_frequent\").fit_transform(\n    df[[\"city\"]]).ravel()\nprint(df)",
