    code: "from sklearn.datasets import load_iris\nfrom sklearn.model_selection import GridSearchCV, train_test_split\nfrom sklearn.svm import SVC\n\nX, y = load_iris(return_X_y=True)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, random_state=0, stratify=y)\n\ngrid = GridSearchCV(SVC(), {\"C\": [0.1, 1, 10], \"kernel\": [\"linear\", \"rbf\"]},\n                    cv=5)\ngrid.fit(X_tr, y_tr)\n\nprint(\"Best params:\", grid.best_params_)\nprint(\"Best CV score:\", round(grid.best_score_, 3))\nprint(\"Test score:\", round(grid.score(X_te, y_te), 3))",
